$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);$q=$pdo->prepare("SELECT p.*,u.full_name farmer_name,u.phone farmer_phone FROM products p JOIN users u ON u.id=p.farmer_id WHERE p.id=? AND p.status='active'");$q->execute([$id?:0]);$p=$q->fetch();if(!$p){http_response_code(404);$pageTitle='Product not found';require __DIR__.'/includes/header.php';echo '<div class="section"><div class="empty-state">This listing is no longer available. <a href="/market.php">Return to the market</a>.</div></div>';require __DIR__.'/includes/footer.php';exit;}
$pageTitle=$p['name'];require __DIR__.'/includes/header.php';
?>
<section class="section"><a class="helper" href="/market.php">← Back to the market</a><div class="two-col" style="margin-top:18px;align-items:start"><?php $artStyle='height:360px;border-radius:20px;font-size:100px'; require __DIR__ . '/includes/product-art.php'; ?><article class="panel"><span class="tag"><?= e($p['category']) ?></span><h1 style="font-size:2.6rem;margin-top:12px"><?= e($p['name']) ?></h1><div class="price" style="font-size:1.7rem"><?= money($p['price']) ?> <small class="product-meta">per <?= e($p['unit']) ?></small></div><p class="muted">Available: <?= e(rtrim(rtrim((string)$p['quantity'],'0'),'.')) ?> <?= e($p['unit']) ?><br>Grown/listed by <strong><?= e($p['farmer_name']) ?></strong><br><?= e($p['location']) ?></p><p><?= nl2br(e($p['description']?:'The farmer has not added a description yet.')) ?></p><?php if(current_user() && (int)current_user()['id']===(int)$p['farmer_id']): ?><a class="button button-quiet" href="/farmer/dashboard.php">Manage your listings</a><?php elseif((current_user()['role']??'')==='buyer'): ?><form method="post" action="/create-order.php"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="product_id" value="<?= (int)$p['id'] ?>"><div class="field"><label for="quantity">How much? (<?= e($p['unit']) ?>)</label><input id="quantity" name="quantity" type="number" min="0.01" max="<?= e($p['quantity']) ?>" step="0.01" value="1" required></div><div class="field"><label for="fulfillment">Pickup or delivery?</label><select id="fulfillment" name="fulfillment"><option value="pickup">Arrange pickup</option><option value="delivery">Ask about delivery</option></select></div><div class="field"><label for="payment_method">Payment preference</label><select id="payment_method" name="payment_method"><option value="to_agree">Agree with farmer</option><option value="cash">Cash</option><option value="bank_transfer">Bank transfer</option><option value="ewallet">Digital wallet</option></select></div><div class="field"><label for="buyer_note">Note to farmer (optional)</label><textarea id="buyer_note" name="buyer_note" maxlength="500" placeholder="When would you like to collect it?"></textarea></div><button class="button">Send order request</button><p class="helper">This creates a request, not a payment. The farmer will contact you to confirm details.</p></form><?php elseif(!current_user()): ?><a class="button" href="/login.php">Log in to order</a><?php else: ?><p class="disclaimer">Buyer accounts can send order requests. Please use a buyer account to purchase.</p><?php endif; ?></article></div></section>
